#!/usr/bin/env python

import subprocess

def activate_microphones(device_list):
    for device in device_list:
        subprocess.run(["amixer", "-c", device, "record"], check=True)

device_list = ["device1", "device2", "device3"]
activate_microphones(device_list)
```

```
#!/usr/bin/env python

import subprocess

def deactivate_microphones(device_list):
    for device in device_list:
        subprocess.run(["amixer", "-c", device, "stop"], check=True)

device_list = ["device1", "device2", "device3"]
deactivate_microphones(device_list)
```

